"""Run queued jobs with their handlers, retrying failed ones a few times."""

from __future__ import annotations

from collections.abc import Callable, Mapping
from typing import Any

from jobq.queue import JobQueue

Handler = Callable[[dict[str, Any]], None]
MAX_ATTEMPTS = 5


class Worker:
    """Takes jobs from a queue and calls the handler registered for their kind."""

    def __init__(self, queue: JobQueue, handlers: Mapping[str, Handler]) -> None:
        self.queue = queue
        self.handlers = handlers

    def run_once(self) -> bool:
        """Run the next pending job; returns False when nothing was pending."""
        if not self.queue.pending:
            return False
        job = self.queue.pending.popleft()
        handler = self.handlers.get(job.kind)
        if handler is None:
            self.queue.dead.append(job)
            return True
        job.attempts += 1
        try:
            handler(job.payload)
        except Exception:
            if job.attempts >= MAX_ATTEMPTS:
                self.queue.dead.append(job)
            else:
                self.queue.pending.append(job)
        else:
            self.queue.done.append(job)
        return True

    def run_all(self) -> None:
        """Run jobs until none are pending."""
        while self.run_once():
            pass

